#!/usr/bin/env node
// Rinkai Shinonome-Shin-kiba: display-only repair of jp-東京臨海高速鉄道-臨海副都心線 intervals 5, 6 and station aliases 004034
// onto the Apple Maps track (repair-01, generated by railway-evidence/local/proposals/repair-01-tools-20261021/emit.mjs).
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {createRequire} from 'node:module';
import {fileURLToPath} from 'node:url';
import {partRowsForLine} from './build-display-lanes.mjs';
import {assertAllowedCandidateFile} from './local-evidence-path.mjs';
import {refreshDependencyReferences, applyPreparedWrites, DEPENDENCY_PATHS} from './repair-three-reversal-extents.mjs';

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const APP = path.join(REPO, 'app'), EV = path.join(REPO, 'railway-evidence/local');
export const AUTHORITY_PATH = path.join(REPO, "railway-evidence/local/proposals/rinkai-shinonome-shinkiba-20261021/bounded-rinkai-shinonome-shinkiba-authority-v1.json");
export const C = {"LINE":"jp-東京臨海高速鉄道-臨海副都心線","KEY":"rinkai-shinonome-shinkiba-display","TITLE":"Rinkai Shinonome-Shin-kiba","STATIONS":["004034"],"INTERVALS":[5,6],"BASELINE_SHA":"2aebfee52d143c2c9366f7c1ba3895d757aaa5dc2f6705406c4082e0c6fbbfe1","CANDIDATE_SHA":"3dac5aa832848ea71e76b54c2c6a43a372b4b27f754c5141832d215a2623ae01","NATIVE_SHA":"e5e5e9a408a4393eb8bce45c77df730936c8f2a78b142dc0fa9748dd3f75406d","POINTS":[167],"BASE_POINTS":[101],"PREFIX_SUFFIX":[[83,1]],"FORMAT":"jtm-rinkai-shinonome-shinkiba-authority-v1","RECEIPT_FORMAT":"jtm-rinkai-shinonome-shinkiba-candidate-review-v1","AUTHORITY":"railway-evidence/local/proposals/rinkai-shinonome-shinkiba-20261021/bounded-rinkai-shinonome-shinkiba-authority-v1.json"};
const {LINE, KEY, STATIONS, INTERVALS} = C;
const net = createRequire(import.meta.url)('../../public/rail-network.js');
const read = p => JSON.parse(fs.readFileSync(p));
const equal = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const sha = value => createHash('sha256').update(JSON.stringify(value)).digest('hex');

function proposedLine(e) {
  assert.deepEqual([e.format, e.lineID, e.stationIDs, e.intervalIndices, e.nativePointCounts, e.MainCertified, e.wholeLineAccepted],
    [C.FORMAT, LINE, STATIONS, INTERVALS, C.POINTS, false, false], C.TITLE + ' authority scope changed');
  assert.equal(sha(e.baselineLine), C.BASELINE_SHA, C.TITLE + ' baseline authority changed');
  assert.equal(sha(e.candidateLine), C.CANDIDATE_SHA, C.TITLE + ' candidate authority changed');
  assert.equal(sha(e.baselineNativeRows), C.NATIVE_SHA, C.TITLE + ' baseline native authority changed');
  const before = e.baselineLine, after = e.candidateLine, reconstructed = structuredClone(before);
  if (INTERVALS.length) reconstructed.displayIntervalCoordinates ??= {};
  for (const i of INTERVALS) reconstructed.displayIntervalCoordinates[i] = structuredClone(after.displayIntervalCoordinates[i]);
  if (STATIONS.length) reconstructed.displayStationCoordinates ??= {};
  for (const id of STATIONS) reconstructed.displayStationCoordinates[id] = structuredClone(after.displayStationCoordinates[id]);
  assert.deepEqual(reconstructed, after, 'Only the listed display intervals and station aliases may change');
  assert.deepEqual(net.decodeIntervals(after), net.decodeIntervals(before), 'Physical source changed');
  const oldParts = net.displayPartsForLine(before), parts = net.displayPartsForLine(after);
  assert.deepEqual(oldParts.map(p => p.length), C.BASE_POINTS, 'baseline public parts changed');
  assert.deepEqual(parts.map(p => p.length), C.POINTS, 'candidate public parts changed');
  C.PREFIX_SUFFIX.forEach(([p, s], k) => {
    assert.deepEqual(parts[k].slice(0, p), oldParts[k].slice(0, p), 'protected prefix changed, part ' + k);
    if (s) assert.deepEqual(parts[k].slice(-s), oldParts[k].slice(-s), 'protected suffix changed, part ' + k);
  });
  return structuredClone(after);
}

export function repairPackage(input, e = read(AUTHORITY_PATH)) {
  const line = proposedLine(e), own = input.lines.filter(l => l.id === LINE);
  assert.equal(own.length, 1, C.TITLE + ' own line missing/duplicated');
  assert(equal(own[0], e.baselineLine) || equal(own[0], line), C.TITLE + ' stale own package baseline');
  const result = structuredClone(input);
  result.lines = result.lines.map(l => l.id === LINE ? line : l);
  const provenance = {lineID: LINE, stationIDs: STATIONS, intervalIndices: INTERVALS,
    evidence: path.relative(REPO, AUTHORITY_PATH), physicalTopologyChanged: false,
    status: 'bounded-apple-track-display-intervals; full-passenger-caps-open', wholeLineAccepted: false, MainCertified: false};
  result.geometrySource ??= {}; result.geometrySource.manualOverrides ??= {};
  const previous = result.geometrySource.manualOverrides[KEY];
  assert(previous === undefined || equal(previous, provenance), C.TITLE + ' provenance changed');
  result.geometrySource.manualOverrides[KEY] = provenance;
  return result;
}

export function repairParts(pkg, input, e = read(AUTHORITY_PATH)) {
  const ownLines = pkg.lines.filter(l => l.id === LINE);
  assert.equal(ownLines.length, 1, C.TITLE + ' candidate line missing/duplicated');
  const line = ownLines[0]; assert.deepEqual(line, proposedLine(e));
  const parts = net.displayPartsForLine(line), rows = partRowsForLine(line, parts, null, null);
  assert.deepEqual(rows.map(r => r[4]), C.POINTS); rows.forEach((r, k) => assert.deepEqual(r[7], parts[k]));
  const own = input.partsByRegion?.jp?.filter(r => r[0] === LINE);
  assert.equal(own?.length, C.POINTS.length, C.TITLE + ' own native rows missing/duplicated');
  assert(equal(own, e.baselineNativeRows) || equal(own, rows), C.TITLE + ' stale/foreign own native row');
  const mentions = v => JSON.stringify(v)?.includes(JSON.stringify(LINE));
  for (const [key, value] of Object.entries(input)) if (key !== 'partsByRegion' && !LANE_KEYS.has(key) && !IDENTITY_KEYS.has(key))
    assert(!mentions(value), C.TITLE + ' own native reference requires review: ' + key);
  for (const key of [...LANE_KEYS, ...IDENTITY_KEYS, 'partsByRegion']) for (const [region, values] of Object.entries(input[key] || {}))
    if (region !== 'jp') assert(!mentions(values), C.TITLE + ' foreign-region own reference: ' + key);
  assert(!(input.excludedOperators || []).includes(line.operator), C.TITLE + ' operator excluded');
  const result = structuredClone(input), at = result.partsByRegion.jp.findIndex(r => r[0] === LINE);
  result.partsByRegion.jp = result.partsByRegion.jp.filter(r => r[0] !== LINE);
  result.partsByRegion.jp.splice(at, 0, ...rows);
  remapLaneReferences(result, e, net.displayPartsForLine(e.baselineLine), parts);
  return result;
}

// Measured lane references: metres along an own part. A reference outside the changed stretch keeps its exact point
// (projection gap < 0.01 m); one inside it moves to the nearest point of the new part (gap <= 25 m); part ends stay ends.
const LANE_KEYS = new Set(['byRegion', 'followsByRegion', 'familyWindowsByRegion', 'hubReportByRegion']);
const IDENTITY_KEYS = new Set(['colorByRegion', 'renderGroupByRegion', 'loopsByRegion', 'chainBoundariesByRegion']);
const metric = (a, b) => { const la = (a[1] + b[1]) * Math.PI / 360; return Math.hypot((b[0] - a[0]) * 111320 * Math.cos(la), (b[1] - a[1]) * 111320); };
const cumulative = pts => pts.reduce((m, p, i) => (m.push(i ? m.at(-1) + metric(pts[i - 1], p) : 0), m), []);
export function remapMeasure(before, after, measure) {
  const om = cumulative(before), nm = cumulative(after), keep = v => Math.abs(measure * 10 - Math.round(measure * 10)) < 1e-6 ? Math.round(v * 10) / 10 : v;
  if (measure <= 0) return measure;
  let same = 0; while (same < Math.min(before.length, after.length) && equal(before[same], after[same])) same++;
  if (same && measure <= om[same - 1]) return measure;  // unchanged prefix: identical measure
  if (measure >= om.at(-1) - 0.05) return keep(nm.at(-1) + (measure - om.at(-1)));
  let i = 1; while (om[i] < measure) i++;
  const f = (measure - om[i - 1]) / (om[i] - om[i - 1]), point = before[i - 1].map((v, k) => v + f * (before[i][k] - v));
  let best;
  for (let j = 0; j < after.length - 1; j++) {
    const a = after[j], b = after[j + 1], c = Math.cos(point[1] * Math.PI / 180), dx = (b[0] - a[0]) * c, dy = b[1] - a[1], d = dx * dx + dy * dy;
    const t = d ? Math.max(0, Math.min(1, ((point[0] - a[0]) * c * dx + (point[1] - a[1]) * dy) / d)) : 0;
    const q = [a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1])], gap = metric(point, q);
    if (!best || gap < best.gap - 1e-9) best = {gap, m: nm[j] + t * metric(a, b)};
  }
  assert(best.gap <= 25, C.TITLE + ' lane measure ' + measure + ' has no counterpart within 25 m');
  return keep(best.m);
}
export function laneReferenceAfter(ref, beforeParts, afterParts) {
  const m = (part, v) => remapMeasure(beforeParts[part], afterParts[part], v);
  const r = structuredClone(ref);
  if (ref.byRegion) r.byRegion = ref.byRegion.map(x => [x[0], x[1], m(x[1], x[2]), m(x[1], x[3]), ...x.slice(4)]);
  if (ref.follows) r.follows = ref.follows.map(x => { const y = [...x];
    if (x[0] === LINE) { y[2] = m(x[1], x[2]); y[3] = m(x[1], x[3]); }
    if (x[4] === LINE) { y[6] = m(x[5], x[6]); y[7] = m(x[5], x[7]); } return y; });
  if (ref.familyWindows) r.familyWindows = ref.familyWindows.map(x => [x[0], x[1], m(x[1], x[2]), m(x[1], x[3]), ...x.slice(4)]);
  if (ref.hubMembers) r.hubMembers = ref.hubMembers.map(({hubId, member}) => ({hubId, member: Object.fromEntries(Object.entries(member)
    .map(([k, v]) => [k, ['from', 'to', 'alongsideFrom', 'alongsideTo'].includes(k) ? m(member.partIndex, v) : v]))}));
  return r;
}
function remapLaneReferences(result, e, beforeParts, afterParts) {
  const ref = e.baselineLaneReferences, next = laneReferenceAfter(ref, beforeParts, afterParts);
  const swap = (rowsOf, before, after, what) => before.forEach((b, k) => {
    const rows = rowsOf(), i = rows.findIndex(x => equal(x, b) || equal(x, after[k]));
    assert(i >= 0, C.TITLE + ' ' + what + ' reference changed: ' + JSON.stringify(b).slice(0, 120));
    rows[i] = after[k];
  });
  swap(() => result.byRegion.jp, ref.byRegion, next.byRegion, 'byRegion');
  swap(() => result.followsByRegion.jp, ref.follows, next.follows, 'follow');
  swap(() => result.familyWindowsByRegion.jp, ref.familyWindows, next.familyWindows, 'family window');
  ref.hubMembers.forEach(({hubId}, k) => {
    const hub = result.hubReportByRegion.jp.find(h => h.hubId === hubId);
    swap(() => hub?.members || [], [ref.hubMembers[k].member], [next.hubMembers[k].member], 'hub ' + hubId);
  });
  const count = (key, f) => (result[key]?.jp || []).filter(f).length;
  assert.equal(count('byRegion', x => x[0] === LINE), ref.byRegion.length, C.TITLE + ' unreviewed byRegion row');
  assert.equal(count('followsByRegion', x => x[0] === LINE || x[4] === LINE), ref.follows.length, C.TITLE + ' unreviewed follow');
  assert.equal(count('familyWindowsByRegion', x => x[0] === LINE), ref.familyWindows.length, C.TITLE + ' unreviewed family window');
  assert.equal((result.hubReportByRegion?.jp || []).flatMap(h => h.members.filter(x => x.lineId === LINE)).length, ref.hubMembers.length,
    C.TITLE + ' unreviewed hub member');
}

export function validateCandidateReview(receipt, line) {
  assert(receipt, C.TITLE + ' scoped candidate-review receipt required before --apply');
  assert.deepEqual([receipt.format, receipt.status, receipt.lineID, receipt.stationIDs, receipt.intervalIndices,
    receipt.MainCertified, receipt.wholeLineAccepted, receipt.continuityCheck?.ok],
  [C.RECEIPT_FORMAT, 'bounded-candidate-reviewed', LINE, STATIONS, INTERVALS, false, false, true], C.TITLE + ' review scope changed');
  assert.equal(receipt.reviewedOwnLineSha256, C.CANDIDATE_SHA, C.TITLE + ' reviewed candidate changed');
  assert.equal(receipt.reviewedOwnLineSha256, sha(line), C.TITLE + ' reviewed own line changed');
}

function main(args) {
  assert(args.length === 3 && args[0] === '--apply' && args[1] === '--candidate-review',
    'Use --apply --candidate-review <canonical evidence receipt.json>');
  const receiptPath = path.resolve(args[2]); assertAllowedCandidateFile(receiptPath);
  assert(fs.realpathSync(receiptPath).startsWith(fs.realpathSync(EV) + path.sep), C.TITLE + ' receipt must use canonical local evidence');
  const snapshot = p => ({path: p, before: fs.readFileSync(p)});
  const authority = snapshot(AUTHORITY_PATH), receipt = snapshot(receiptPath), e = JSON.parse(authority.before);
  const paths = {package: 'public/rail/jp-2025.json', lanes: 'public/rail/display-lanes.json', ...DEPENDENCY_PATHS};
  const inputs = Object.fromEntries(Object.entries(paths).map(([k, p]) => [k, snapshot(path.join(APP, p))]));
  const load = k => JSON.parse(inputs[k].before), pkg = repairPackage(load('package'), e);
  validateCandidateReview(JSON.parse(receipt.before), pkg.lines.find(l => l.id === LINE));
  const lanes = repairParts(pkg, load('lanes'), e);
  const dependencies = refreshDependencyReferences(pkg, Object.fromEntries(Object.keys(DEPENDENCY_PATHS).map(k => [k, load(k)])));
  const outputs = {package: JSON.stringify(pkg), lanes: JSON.stringify(lanes) + '\n',
    ...Object.fromEntries(Object.entries(dependencies).map(([k, v]) => [k, JSON.stringify(v, null, 2) + '\n']))};
  const writes = Object.entries(outputs).map(([k, after]) => ({...inputs[k], after: Buffer.from(after)}));
  const implementation = ['public/rail-network.js', 'scripts/railway/build-display-lanes.mjs',
    'scripts/railway/repair-three-reversal-extents.mjs', 'scripts/railway/local-evidence-path.mjs',
    'scripts/railway/repair-rinkai-shinonome-shinkiba-display.mjs'].map(p => snapshot(path.join(APP, p)));
  applyPreparedWrites(writes, [...Object.values(inputs), authority, receipt, ...implementation]);
  console.log(JSON.stringify({mode: 'applied', lineID: LINE, stationIDs: STATIONS, intervalIndices: INTERVALS,
    nativeRows: lanes.partsByRegion.jp.filter(r => r[0] === LINE).map(r => r.slice(0, 7)),
    fullPassengerCapsCertified: false, wholeLineAccepted: false, MainCertified: false}));
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main(process.argv.slice(2));
